import {galleryFor,boundedIndex,boundedZoom} from './gallery.mjs';
import {hydrate,productFor,recordSearch,recordView,searchProducts,recommendations,dropPrice,auctionDiscoveryAlert,assistantReply} from './personalization.mjs';
import {products,missions,freshState,missionReady,claim,placeBid,compete,closeAuction,purchase,redeem,releasePoints} from './core.mjs';
const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let state=freshState(),hasSavedState=false;try{const saved=JSON.parse(localStorage.getItem('vidaxl-demo-v1'));if(saved?.version===1&&Array.isArray(saved.saved)&&saved.auction){state=saved;hasSavedState=true;}}catch{}if(!hasSavedState)state.member=false;
hydrate(state);
let revealObserver=null,gallerySelections={},zoomProduct=null,zoomScale=1,motionTimer,lastRenderedRoute='',searchTimer,notificationFilter='All',shopSort='recommended',pendingAuthRoute='home',chatContext=null,chatBusy=false,splashTimer=null,splashShown=false;
let route=location.hash.slice(1)||'splash',category='All',auctionFilter='Live',query='',modal='',voucher=10,error='',trail=[],previousFocus=null,ugcPhoto='';
const paths={tag:'M3 3h7l11 11-7 7L3 10V3 M7 7h.01',hammer:'m14 3 7 7-3 3-7-7 3-3 M9 8l7 7 M4 21l9-9 M2 22h8',gift:'M3 8h18v4H3z M5 12v9h14v-9 M12 8v13 M12 8H8a3 3 0 1 1 3-3l1 3 M12 8h4a3 3 0 1 0-3-3l-1 3',support:'M4 14v-3a8 8 0 0 1 16 0v3 M4 11H2v7h4v-7H4 M20 11h2v7h-4v-7h2 M20 18c0 3-4 4-7 4',heart:'M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8',bell:'M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9 M10 21h4',search:'M10 18a8 8 0 1 0 0-16 8 8 0 0 0 0 16 M16 16l6 6',chevron:'m9 5 7 7-7 7',back:'m15 5-7 7 7 7',close:'m6 6 12 12 M6 18 18 6',check:'m4 12 5 5L20 6',star:'m12 2 3 6 7 1-5 5 1 7-6-3-6 3 1-7-5-5 7-1 3-6',user:'M12 12a5 5 0 1 0 0-10 5 5 0 0 0 0 10 M3 22v-3a9 9 0 0 1 18 0v3',box:'m12 2 10 5v10l-10 5-10-5V7l10-5 M2 7l10 5 10-5 M12 12v10 M7 4l10 5',camera:'M3 6h4l2-3h6l2 3h4v15H3V6 M12 17a4 4 0 1 0 0-8 4 4 0 0 0 0 8',clock:'M12 22a10 10 0 1 0 0-20 10 10 0 0 0 0 20 M12 6v6l4 2',leaf:'M20 3C9 2 2 7 4 15c3 6 14 6 16-12 M4 21 15 10',eye:'M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12 M12 15a3 3 0 1 0 0-6 3 3 0 0 0 0 6',arrow:'M5 12h14 m-6-6 6 6-6 6',spark:'m12 2 3 7 7 3-7 3-3 7-3-7-7-3 7-3 3-7',external:'M14 3h7v7 M21 3 10 14 M10 3H3v18h18v-7',settings:'M4 7h16 M4 12h16 M4 17h16 M8 5v4 M16 10v4 M10 15v4'};
const icon=(n)=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[n]||paths.star}"/></svg>`;
const btn=(label,action,cls='primary',extra='')=>`<button class="${cls}" data-action="${action}" ${extra}>${label}</button>`;
const money=n=>`€${Number(n).toFixed(2).replace('.00','')}`;
const prod=id=>productFor(state,id)||productFor(state,products[0].id);
function save(){try{localStorage.setItem('vidaxl-demo-v1',JSON.stringify(state));}catch{}}
function log(name){state.events.push({name,at:Date.now()});save();}
function toast(msg){$('#toast').textContent=msg;$('#toast').style.display='block';clearTimeout(toast.t);toast.t=setTimeout(()=>$('#toast').style.display='none',3200);}
function navigate(next,push=true){if(!state.member&&['rewards','orders','activity','preferences','supportform','ugc'].includes(next)){pendingAuthRoute=next;next='login';}if(next.startsWith('offer:'))recordView(state,next.split(':')[1]);hydrate(state);if(next==='home')auctionDiscoveryAlert(state);if(push){trail.push(route);history.pushState({},'',`#${next}`);}route=next;query='';error='';dismiss(false);const update=()=>{render();window.scrollTo({top:0,behavior:'instant'});$('#main').focus({preventScroll:true});};if(document.startViewTransition&&!(typeof matchMedia==='function'&&matchMedia('(prefers-reduced-motion: reduce)').matches)){const transition=document.startViewTransition(update);transition.ready.catch(()=>{});}else update();}
window.addEventListener('popstate',()=>{route=location.hash.slice(1)||'home';dismiss(false);render();window.scrollTo(0,0);});
function dismiss(focus=true){modal='';$('#overlay').innerHTML='';document.body.style.overflow='';if(focus&&previousFocus?.isConnected)previousFocus.focus();}
function sheet(title,content,key){modal=key;previousFocus=document.activeElement;$('#overlay').innerHTML=`<div class="sheet-backdrop" data-action="backdrop"><section class="sheet" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="sheet-top"><h2>${title}</h2>${btn(icon('close'),'dismiss','icon-btn','aria-label="Close dialog"')}</div>${content}</section></div>`;document.body.style.overflow='hidden';$('.sheet button,.sheet input,.sheet a')?.focus();}
document.addEventListener('keydown',e=>{if(!modal)return;if(e.key==='Escape')dismiss();if(e.key==='Tab'){const a=[...$('.sheet').querySelectorAll('button:not(:disabled),a[href],input,select,textarea')];if(!a.length)return;const first=a[0],last=a.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});
function headerLegacy(){const root=['offers','auctions','rewards','support'].includes(route);const names={auction:'Live auction',saved:'Saved offers',orders:'Your orders',profile:'Your account',preferences:'Home preferences',ugc:'Share your home',inbox:'Notifications',join:'Join vidaXL+',welcome:'Welcome',activity:'Point activity',supportform:'Contact support',tracking:'Order details'};$('#header').innerHTML=`<div class="topbar">${root?`<div class="brand"><img src="assets/logo.svg" alt="vidaXL"><span class="plus" aria-label="Plus">+</span></div>`:`<div class="backtitle">${btn(icon('back'),'back','icon-btn','aria-label="Go back"')}<h2>${names[route]||(route.startsWith('offer:')?'Member offer':route.startsWith('tracking:')?'Order details':route.startsWith('ticket:')?'Support request':'vidaXL+')}</h2></div>`}<div class="header-actions">${root?btn(icon('bell')+(state.notices.length?'<span class="dot"></span>':''),'go:inbox','icon-btn','aria-label="Notifications"'):''}${btn(esc(state.member?state.name.slice(0,1).toUpperCase():'?'),'go:profile','icon-btn avatar','aria-label="Your account"')}</div></div>`;}
function navigationLegacy(){const tab=route.startsWith('offer')||['saved','welcome','join'].includes(route)?'offers':['auction','auctions'].includes(route)?'auctions':['rewards','preferences','ugc','activity'].includes(route)?'rewards':route.startsWith('support')||route.startsWith('ticket')?'support':'';$('#nav').innerHTML=`<div class="nav">${[['offers','tag','Offers'],['auctions','hammer','Auctions'],['rewards','gift','Rewards'],['support','support','Support']].map(([r,i,l])=>btn(`<span class="navicon">${icon(i)}</span>${l}`,`go:${r}`,tab===r?'active':'',tab===r?'aria-current="page"':'')).join('')}</div>`;}
function title(text,sub=''){return `<h1>${text}</h1>${sub?`<p class="subtitle">${sub}</p>`:''}`;}
function progress(n,max){return `<div class="progress" role="progressbar" aria-label="Progress" aria-valuemin="0" aria-valuemax="${max}" aria-valuenow="${Math.min(n,max)}"><span style="width:${Math.min(100,n/max*100)}%"></span></div>`;}
function empty(i,h,p,button=''){return `<div class="empty">${icon(i)}<h2>${h}</h2><p>${p}</p>${button}</div>`;}
function productCardLegacy(p){return `<article class="product"><div class="product-photo">${btn(`<img src="assets/${p.image}" alt="${p.name}" loading="lazy">`,`go:offer:${p.id}`,'','aria-label="View '+p.name+'"')}${btn(icon('heart'),`save:${p.id}`,'icon-btn save '+(state.saved.includes(p.id)?'is-saved':''),`aria-label="${state.saved.includes(p.id)?'Unsave':'Save'} ${p.name}" aria-pressed="${state.saved.includes(p.id)}"`)}</div><div class="product-label">${p.tag}</div><h3>${p.name}</h3><div class="price">${money(p.price)} <del>${money(p.original)}</del></div><div class="earn">${p.points} purchase points · pending first</div></article>`;}
function offerResults(){const rows=searchProducts(state,query,category);if(shopSort==='low')rows.sort((a,b)=>a.price-b.price);if(shopSort==='high')rows.sort((a,b)=>b.price-a.price);return rows.length?`<div class="product-grid">${rows.map(productCard).join('')}</div>`:empty('search','No offers found','Try a different word or category.',btn('Clear search','clearsearch','secondary'));}
function offersLegacy(){return `<p class="greeting">${state.member?`Welcome back, ${esc(state.name)}`:'Welcome to vidaXL+'}</p>${title('Your home.<br>More rewarding.','Member offers for the spaces you love.')}<label class="search">${icon('search')}<input id="search" type="search" placeholder="Search member offers" aria-label="Search member offers" value="${esc(query)}"></label><div class="categories">${['All','Garden','Furniture','Bedroom'].map(c=>btn(c,`category:${c}`,'chip '+(category===c?'active':''),`aria-pressed="${category===c}"`)).join('')}${btn(icon('heart'),'go:saved','chip','aria-label="Saved offers"')}</div>${category==='All'&&!query?`<section class="hero"><img src="assets/bedroom.jpg" alt="A thoughtfully styled vidaXL bedroom"><div class="hero-body"><span class="pill lemon">ONLY FOR MEMBERS</span><h2>Make room<br>for a little more.</h2><p>Discover thoughtful finds.<br>Enjoy a better member price.</p>${btn('Explore today’s offers '+icon('arrow'),'scrolloffers')}</div></section>`:''}<button class="balance-mini full" data-action="go:rewards" style="border:0;text-align:left"><div><small>Your vidaXL+ balance</small><b>${state.points} points</b> <small style="display:inline">· ${money(state.points*.5)} in reward value</small></div>${icon('chevron')}</button><section class="section" id="offers-section"><div class="section-head"><h2>${category==='All'?'Picked for your home':category+' offers'}</h2><small>Demo member prices</small></div><div id="offer-results">${offerResults()}</div></section><section class="section card"><div class="task-preview"><div class="task-icon">${icon('spark')}</div><div><h3>Your next little win</h3><p>Complete a mission. Unlock a reward.</p></div></div>${progress(state.claims.length,3)}<div class="row spread"><small>${state.claims.length} of 3 missions completed</small>${btn('Explore missions →','go:rewards','text-btn')}</div></section><div class="section-head section"><h2>Something worth watching</h2>${btn('All auctions','go:auctions','text-btn')}</div><button class="card full row" style="text-align:left" data-action="go:auction"><img src="assets/bench.jpg" alt="Garden bench" width="70" height="65" style="object-fit:contain"><div><h3>A new favourite for your garden</h3><p class="small">${['won','lost'].includes(state.auction.status)?'Auction ended':'Live auction · from '+money(state.auction.current)}</p></div>${icon('chevron')}</button>`;}
function offerDetailLegacy(id){const p=prod(id);return `<div class="image-large"><img src="assets/${p.image}" alt="${p.name}"><span class="pill lemon">MEMBER OFFER</span></div><span class="eyebrow" style="color:var(--plum)">${p.category}</span><h1 class="detail-title">${p.name}</h1><p>${p.description}</p><div class="facts"><div><small>Member price</small><b>${money(p.price)}</b></div><div><small>Regular demo price</small><b style="color:var(--muted);text-decoration:line-through">${money(p.original)}</b></div><div><small>You save</small><b style="color:var(--plum)">${money(p.original-p.price)}</b></div></div><div class="row spread mb"><span class="pill green">Offer available</span><small>Sample offer · ends in 2 days</small></div>${btn('Unlock member offer '+icon('arrow'),`unlock:${p.id}`,'primary full')}<button class="secondary full mt" data-action="save:${p.id}">${icon('heart')}${state.saved.includes(p.id)?'Saved to your offers':'Save for later'}</button><section class="section"><h2>Good to know</h2><details class="faq" open><summary>Your member offer</summary><p>Sample member price shown for this concept. Product availability, shipping and the final price are confirmed on the webshop. Offer discounts and points vouchers are shown as separate choices.</p></details><details class="faq"><summary>Earn points on your purchase</summary><p>Qualifying purchases earn 1 point per €12.50. Purchase points remain pending during the 30-day waiting period. Returns can affect your points.</p></details><details class="faq"><summary>Shopping on the webshop</summary><p>Continue to vidaXL’s webshop to complete a real purchase. This demo separately lets you preview an order confirmation without buying anything.</p></details></section>`;}
function auctionStatus(){return ({ready:'Live now',leading:'You’re leading',outbid:'You’ve been outbid',won:'You won',lost:'Auction ended'})[state.auction.status];}
function auctionCard(){return `<article class="card auction-card"><div class="auction-picture"><img src="assets/bench.jpg" alt="Garden bench"><span class="pill ${state.auction.status==='leading'||state.auction.status==='won'?'green':state.auction.status==='outbid'?'red':''}">${auctionStatus()}</span>${btn(icon('eye'),'watch:bench','icon-btn save '+(state.watched.includes('bench')?'is-saved':''),`aria-label="${state.watched.includes('bench')?'Unwatch':'Watch'} garden bench" aria-pressed="${state.watched.includes('bench')}"`)}</div><div class="auction-info"><h3>Garden bench with cushions</h3><div class="auction-meta"><div><small>${['won','lost'].includes(state.auction.status)?'Final bid':'Current highest bid'}</small><b>${money(state.auction.current)}</b></div><div style="text-align:right"><small>${['won','lost'].includes(state.auction.status)?'Status':'Time remaining'}</small><span class="clock" data-clock>${clock()}</span></div></div>${btn(['won','lost'].includes(state.auction.status)?'View outcome':'View auction '+icon('arrow'),'go:auction','primary full')}</div></article>`;}
function auctions(){const shown=auctionFilter==='Live'?!['won','lost'].includes(state.auction.status):auctionFilter==='Watching'?state.watched.includes('bench'):auctionFilter==='My bids'?state.auction.max>0:['won','lost'].includes(state.auction.status);return `${title('A find worth bidding for.','Set your limit. We’ll take care of the bidding.')}<div class="categories mt">${['Live','Watching','My bids','Ended'].map(f=>btn(f,`afilter:${f}`,'chip '+(auctionFilter===f?'active':''),`aria-pressed="${auctionFilter===f}"`)).join('')}</div>${shown?auctionCard():empty('hammer','Nothing here yet',auctionFilter==='Watching'?'Watch an auction to keep it close.':'Explore a live auction or try a different tab.',btn('Explore auctions','afilter:Live','secondary'))}<section class="section card"><div class="row"><div class="task-icon">${icon('hammer')}</div><h3>Bidding, made simpler</h3></div><p class="small mt">Choose the most you’re happy to pay. Automatic bidding only raises your bid as needed, up to your limit.</p>${btn('How it works','howauction','text-btn mt')}</section>`;}
function clock(){const s=Math.max(0,Math.ceil((state.auction.end-Date.now())/1000));return ['won','lost'].includes(state.auction.status)?'Ended':`${Math.floor(s/60).toString().padStart(2,'0')}:${(s%60).toString().padStart(2,'0')}`;}
function auctionDetail(){const a=state.auction;const ended=['won','lost'].includes(a.status);let outcome='';if(a.status==='leading')outcome=`<div class="notice"><b>${icon('check')} You’re currently leading</b><p>Your maximum is ${money(a.max)}. Your current bid is ${money(a.current)}. We’ll bid automatically within your limit.</p></div>`;if(a.status==='outbid')outcome=`<div class="notice outbid"><b>You’ve been outbid</b><p>The current bid has exceeded your ${money(a.max)} maximum. You can raise your limit if you wish.</p></div>`;if(a.status==='won')outcome=`<div class="notice"><b>You won for ${money(a.current)}</b><p>Your demo payment and order are confirmed. Your order has been added to your account.</p>${btn('View your order →','go:orders','text-btn')}</div>`;if(a.status==='lost')outcome=`<div class="notice outbid"><b>This auction has ended</b><p>You didn’t win this time. Your demo authorization is released. Still interested in this item?</p></div><div class="card soft"><span class="pill">ANOTHER WAY TO MAKE IT YOURS</span><h2 class="mt">Your member offer is here.</h2><p class="small mt">Garden bench · ${money(prod('bench').price)} member price</p>${btn('Explore your offer →','go:offer:bench','primary full mt')}</div>`;return `<div class="image-large"><img src="assets/bench.jpg" alt="Garden bench with cushions"><span class="pill ${a.status==='leading'||a.status==='won'?'green':''}">${auctionStatus()}</span>${btn(icon('eye'),'watch:bench','icon-btn save '+(state.watched.includes('bench')?'is-saved':''),'aria-label="Toggle auction watchlist" style="top:20px;right:20px"')}</div><h1 class="detail-title">Your new garden<br>gathering spot.</h1><p class="small">Garden bench with cushions · acacia wood</p><div class="facts"><div><small>${ended?'Final bid':'Highest bid'}</small><b>${money(a.current)}</b></div><div><small>Time remaining</small><b class="clock" data-clock>${clock()}</b></div><div><small>Bids placed</small><b>${a.bids}</b></div></div>${outcome}${!ended?`<form id="bid-form"><label class="field"><span>Your maximum bid</span><input name="bid" type="number" min="${Math.max(a.current+1,a.max+1)}" step="1" inputmode="numeric" value="${Math.max(a.current+5,a.max+5)}" required><span class="help">Minimum ${money(Math.max(a.current+1,a.max+1))} · whole-euro increments in this demo</span></label><p class="small">Your limit is private. We only bid as much as needed to keep you leading.</p>${error?`<p class="error" role="alert">${esc(error)}</p>`:''}<button class="primary full mt" type="submit">${a.max?'Raise maximum bid':'Review your bid'} ${icon('arrow')}</button></form><p class="small mt">Late bids can extend the auction. The timer reflects the latest closing time.</p>`:''}<section class="section"><details class="faq"><summary>Automatic bidding and closing time</summary><p>Competing bids can trigger automatic bids up to your private maximum. Bids near the end can extend the closing time. The exact production increments and extension window need client confirmation.</p></details><details class="faq"><summary>Delivery and payment</summary><p>Before your first bid, your delivery details and payment authorization are required. This POC uses a seeded address and simulated authorization. No card details are collected or charged.</p></details><details class="faq"><summary>About this item</summary><p>Acacia wood in greywash, with a shared table. The real product page confirms exact dimensions, included cushions and availability.</p></details><details class="faq"><summary>Preview auction outcomes · demo</summary><p>Use these controls to try the live states without waiting. No real bids are placed.</p><div class="two-actions">${btn('Competing bid','compete','secondary',''+(!a.max||ended?'disabled':''))}${btn('Close auction','closeauction','secondary',ended?'disabled':'')}</div>${btn('Restart this auction','restartauction','text-btn mt')}</details></section>`;}
function missionCard(m){const done=state.claims.includes(m.id),ready=missionReady(state,m.id);let extras=m.id==='explore'?`<div class="mission-checks"><span class="${state.categories.length>=2?'done':''}">${state.categories.length>=2?'✓ ':''}2 categories</span><span class="${state.saved.length?'done':''}">${state.saved.length?'✓ ':''}Save an offer</span><span class="${state.watched.length?'done':''}">${state.watched.length?'✓ ':''}Watch an auction</span></div>`:m.id==='orders'?progress(Math.min(state.orderStreak??1,2),2)+`<small>${Math.min(state.orderStreak??1,2)} / 2 orders this quarter</small>`:'';return `<article class="mission"><div class="row spread"><h3>${m.title}</h3><span class="pill ${done?'green':''}">${done?'✓ Claimed':'+'+m.points+' points'}</span></div><p>${m.detail}</p>${extras}${done?'':ready?btn('Claim '+m.points+' points',`claim:${m.id}`,'primary full'):btn(m.id==='profile'?'Add home preferences':m.id==='explore'?'Start exploring':'Explore member offers',m.id==='profile'?'go:preferences':'go:offers','secondary full mt')}</article>`;}
function rewards(){return `${title('Your little extras.','Earn points. Enjoy more. Make every visit count.')}<section class="card reward-card mt"><div class="row spread"><span class="eyebrow">AVAILABLE POINTS</span><span class="pill tier-pill">${icon('star')} ${state.tier} member</span></div><div class="big-points"><strong data-reward-count="${state.points}">${state.points}</strong><span style="font-size:15px;margin-left:7px">points</span></div><p class="small mt">${money(state.points*.5)} in reward value</p>${progress(state.tierProgress,100)}<div class="tier-row"><span>${state.tier==='Gold'?'Gold benefits unlocked':Math.max(0,100-state.tierProgress)+' progress points to Gold'}</span><span>${state.tier==='Gold'?'✓':state.tierProgress+' / 100'}</span></div>${btn(state.coupon&&!state.coupon.used?'View your reward voucher':'Use your points','redeem','secondary')}</section><button class="pending-row full" data-action="pending" style="border:0;background:white;text-align:left"><span>${state.pending} purchase points pending</span><span>How it works ${icon('chevron')}</span></button><section class="section"><div class="section-head"><h2>Small steps. Real rewards.</h2><span class="count">${state.claims.length}/3 completed</span></div>${missions.map(missionCard).join('')}</section><section class="section card"><div class="row spread"><div><span class="eyebrow" style="color:var(--plum)">YOUR DISCOVERY STREAK</span><h3 style="margin-top:6px">Keep your ideas growing.</h3></div>${icon('leaf')}</div><p class="small mt">Return on 3 days this week to grow your home inspiration streak. Shopping is optional.</p><div class="streak-days">${[1,2,3].map(n=>`<span class="streak-day ${state.streak>=n?'complete':''}">${state.streak>=n?'✓':n}<small>Day ${n}</small></span>`).join('')}</div><p class="small">${state.streak>=3?'Home explorer badge unlocked. Nicely done!':'2 days explored · one more to unlock your badge'}</p>${btn('Your badges','badges','text-btn mt')}</section><section class="section card"><div class="task-preview"><div class="task-icon">${icon('camera')}</div><div><h3>Show us your corner of home.</h3><p>Share your setup. Inspire someone else.</p></div></div>${btn(state.ugcApproved?'Your photo mission is complete':state.ugcPending?'Submission awaiting review':'Share a photo · +5 points','go:ugc','secondary full mt')}</section><section class="section"><div class="section-head"><h2>Your member benefits</h2>${btn('See all','benefits','text-btn')}</div><div class="card soft"><div class="row">${icon('support')}<h3>${state.tier==='Gold'?'Priority support, for you.':'A little closer to Gold.'}</h3></div><p class="small mt">${state.tier==='Gold'?'Your support requests take the priority route.':'Gold unlocks priority support in this concept. Your standard support is always here.'}</p>${btn('Explore your support','go:support','text-btn mt')}</div>${btn('View point activity →','go:activity','text-btn mt')}</section>`;}
function support(){return `${title('Here to help.','Find an answer or reach someone who can help.')}<section class="support-banner mt"><span class="pill ${state.tier==='Gold'?'lemon':''}">${state.tier==='Gold'?'GOLD MEMBER BENEFIT':'MEMBER SUPPORT'}</span><h2>${state.tier==='Gold'?'A faster route to support.':'Let’s make it right.'}</h2><p>${state.tier==='Gold'?'Your membership gives your request priority. Tell us what you need and we’ll keep it together.':'Get help with orders, products, rewards or auctions.'}</p>${btn('Contact support '+icon('arrow'),'go:supportform','primary full mt')}</section><div class="section-head section"><h2>Help with an order</h2>${btn('All orders','go:orders','text-btn')}</div>${state.orders.slice(0,1).map(orderCard).join('')}<section class="section"><h2 class="mb">Quick answers</h2><details class="faq"><summary>When can I use my purchase points?</summary><p>Purchase points have a 30-day waiting period. You can see pending and available points separately in Rewards.</p></details><details class="faq"><summary>How does automatic bidding work?</summary><p>Set your private maximum. The system raises your bid only as needed, up to that limit. If the other bidder exceeds it, you’ll see an outbid status.</p></details><details class="faq"><summary>How do I track my order?</summary><p>Open Your orders, select an order, then view its delivery status. This demo shows sample order data.</p></details><details class="faq"><summary>Can I combine an offer with a points voucher?</summary><p>Reward discounts cannot be combined with other discounts under the published programme. The webshop confirms the eligible choice.</p></details></section><section class="section"><div class="section-head"><h2>Your support requests</h2><span class="count">${state.tickets.length}</span></div>${state.tickets.length?state.tickets.map(t=>btn(`<div><h3>${esc(t.topic)}</h3><p class="small">${t.id} · ${t.priority?'Priority':'Standard'} · Submitted</p></div>${icon('chevron')}`,`go:ticket:${t.id}`,'card full row spread mb','style="text-align:left"')).join(''):'<p class="small">No open requests. We’re here whenever you need us.</p>'}</section>`;}
function orderCard(o){const p=prod(o.product);return `<article class="order"><div class="row spread"><small>${o.id}</small><span class="pill ${o.status==='Delivered'?'green':''}">${o.status}</span></div><div class="row mt"><img src="assets/${p.image}" alt="${p.name}"><div><h3>${p.name}</h3><small>${money(o.amount)} · ${o.points} purchase points</small></div></div><div class="two-actions">${btn('View order',`go:tracking:${o.id}`,'secondary')}${btn('Get help',`orderhelp:${o.id}`,'secondary')}</div></article>`;}
function tracking(id){const o=state.orders.find(o=>o.id===id)||state.orders[0];if(!o)return empty('box','No order to show','Explore member offers to start a demo purchase.',btn('Explore offers','go:offers'));const p=prod(o.product);return `${title('Your order, at a glance.')}<div class="mt">${orderCard(o)}</div><section class="card"><h3>Delivery progress</h3><div class="stack mt">${['Confirmed','Preparing','On its way','Delivered'].map((t,i)=>`<div class="row"><span class="pill ${i<=['Confirmed','Preparing','On its way','Delivered'].indexOf(o.status)?'green':''}">${i<=['Confirmed','Preparing','On its way','Delivered'].indexOf(o.status)?'✓':i+1}</span><span>${t}</span></div>`).join('')}</div><p class="small mt">Sample tracking for this concept. Delivery dates are confirmed by the webshop.</p></section><div class="card soft mt"><h3>Your purchase points</h3><p class="small mt">${o.points} points ${o.status==='Delivered'?'shown with this order. Check Rewards for availability.':'are pending during the waiting period.'}</p>${btn('View rewards →','go:rewards','text-btn mt')}</div>${btn('Explore this product again',`go:offer:${p.id}`,'secondary full mt')}`;}
function supportForm(){return `${title('Tell us what you need.','Your account and order context stay with your request.')}<form id="support-form"><label class="field"><span>What can we help with?</span><select name="topic" required><option>Order and delivery</option><option>Product question</option><option>Rewards and points</option><option>Auction and bidding</option><option>Something else</option></select></label><label class="field"><span>Related order <small>Optional</small></span><select name="order"><option value="">Not related to an order</option>${state.orders.map(o=>`<option ${supportForm.order===o.id?'selected':''}>${o.id}</option>`).join('')}</select></label><label class="field"><span>Your message</span><textarea name="message" required minlength="10" maxlength="2000" placeholder="Let us know what happened and how we can help."></textarea><span class="help">At least 10 characters. Please use sample information for this demo.</span></label><div class="card soft"><div class="row">${icon('support')}<div><h3>${state.tier==='Gold'?'Priority member route':'Standard member route'}</h3><p class="small">Your request will stay visible in Support.</p></div></div></div><button class="primary full mt" type="submit">Send demo request ${icon('arrow')}</button><p class="small mt">This creates a local demo request. Nothing is sent to vidaXL.</p></form>`;}
function profileLegacy(){return `${title(state.member?`Hello, ${esc(state.name)}.`:'Your membership starts here.',state.member?'Your home, your benefits, your preferences.':'More value for the spaces you love.')}<div class="card soft mt"><div class="row spread"><div><h3>${state.member?state.tier+' member':'Join vidaXL+'}</h3><p class="small">${state.member?state.points+' available points':'Member offers, rewards and more'}</p></div>${icon('star')}</div>${!state.member?btn('Create demo membership','go:join','primary full mt'):''}</div>${[['user','Home preferences','preferences'],['heart','Saved offers','saved'],['box','Your orders','orders'],['gift','Point activity','activity'],['bell','Notifications','inbox']].map(([i,l,r])=>btn(`${icon(i)}${l}<span class="end">${icon('chevron')}</span>`,`go:${r}`,'menu-row')).join('')}<div class="menu-row">${icon('bell')}Auction alerts<button class="toggle ${state.notifications?'on':''} end" data-action="notifications" role="switch" aria-checked="${state.notifications}" aria-label="Auction alerts"></button></div><p class="small mt">In this demo, alerts appear inside the app. Real push permission would be requested when you choose to watch an auction.</p>${btn('About this concept & demo controls','demo','menu-row')}${btn(state.member?'Leave member preview':'Explore as a returning member',state.member?'signout':'member','text-btn mt')}`;}
function preferences(){return `${title('A home that feels like you.','Share a little about your space for more useful inspiration.')}<div class="card soft mt"><span class="pill">MISSION · +10 POINTS</span><p class="small mt">Complete these preferences, then claim your reward. You can change your choices later.</p></div><form id="preferences-form"><label class="field"><span>What should we call you?</span><input name="name" value="${esc(state.name)}" maxlength="30" required></label><label class="field"><span>Your next home project</span><select name="project"><option>Garden refresh</option><option>Living room update</option><option>Bedroom comfort</option><option>Storage and organisation</option></select></label><label class="field"><span>Your favourite style</span><select name="style"><option>Natural and relaxed</option><option>Modern and minimal</option><option>Classic and cosy</option><option>Still exploring</option></select></label><p class="small">Optional preferences for this concept; stored only in this browser. Completing the mission does not subscribe you to marketing.</p><button class="primary full mt" type="submit">Save preferences ${icon('check')}</button></form>`;}
function ugc(){return `${title('Your home. Their inspiration.','Show how you’ve made a vidaXL find your own.')}<div class="card soft mt"><span class="pill">SHARE YOUR HOME · +5 POINTS</span><p class="small mt">Points become available after a submission is approved. This is an illustrative app reward.</p></div>${state.ugcPending||state.ugcApproved?`<div class="notice mt"><b>${state.ugcApproved?'Your demo photo has been approved.':'Your submission is awaiting review.'}</b><p>${state.ugcApproved?'+5 points have been added to your rewards.':'We’ll show your reward here after approval.'} No photo has been sent to vidaXL.</p></div>${btn('Back to rewards','go:rewards','primary full mt')}`:`<form id="ugc-form"><div class="upload">${icon('camera')}<h3 class="mt">Choose a photo of your space</h3><p class="small mt">JPG, PNG or WebP · up to 5 MB</p><label class="field"><span class="small">Photo</span><input name="photo" type="file" accept="image/jpeg,image/png,image/webp" required></label><div id="photo-preview"></div></div><label class="field"><span>Your story</span><textarea name="caption" placeholder="What do you love about your space?" required minlength="5" maxlength="500"></textarea></label><label class="checks"><input type="checkbox" name="consent" required><span>I confirm I can share this photo and agree to this demo submission. No photo will be uploaded or published.</span></label><button class="primary full" type="submit">Submit for demo review</button></form>`}`;}
function welcome(){return `<img class="onboard-hero" src="assets/bedroom.jpg" alt="vidaXL bedroom inspiration"><span class="eyebrow" style="color:var(--plum)">WELCOME TO VIDAXL+</span><h1 class="detail-title">A little more home.<br>A little less spend.</h1><p>Your favourite finds, member rewards and a new way to discover.</p><div class="stack section">${[['tag','Member-only offers'],['hammer','Auctions you can follow'],['gift','Rewards that add up']].map(([i,t])=>`<div class="row"><div class="task-icon">${icon(i)}</div><h3>${t}</h3></div>`).join('')}</div>${btn('Create demo membership','go:join','primary full section')}${btn('Explore as a returning member','member','secondary full mt')}`;}
function joinLegacy(){return `${title('Make yourself at home.','Create a sample membership to explore the complete journey.')}<form id="join-form"><label class="field"><span>Your first name</span><input name="name" placeholder="Alex" maxlength="30" required></label><label class="checks"><input name="terms" type="checkbox" required><span>I understand this is a concept using sample membership data.</span></label><button class="primary full mt" type="submit">Join demo membership ${icon('arrow')}</button><p class="small mt">No email, password or payment information is needed. Welcome-point rules will be confirmed with the client.</p></form>`;}
function renderLegacy(){header();navigation();let content='';if(route==='offers')content=offers();else if(route.startsWith('offer:'))content=offerDetail(route.split(':')[1]);else if(route==='auctions')content=auctions();else if(route==='auction')content=auctionDetail();else if(route==='rewards')content=rewards();else if(route==='support')content=support();else if(route==='supportform')content=supportForm();else if(route==='profile')content=profile();else if(route==='preferences')content=preferences();else if(route==='ugc')content=ugc();else if(route==='welcome')content=welcome();else if(route==='join')content=join();else if(route==='saved')content=title('Keep the good finds.','Your saved member offers, all in one place.')+`<section class="section">${state.saved.length?`<div class="product-grid">${products.filter(p=>state.saved.includes(p.id)).map(productCard).join('')}</div>`:empty('heart','Your next favourite is out there.','Save an offer with the heart to find it here.',btn('Explore offers','go:offers'))}</section>`;else if(route==='orders')content=title('Your orders.','Everything you’ve brought home, in one place.')+`<section class="section">${state.orders.length?state.orders.map(orderCard).join(''):empty('box','Your first find is waiting.','Orders will appear here after a purchase.',btn('Explore member offers','go:offers'))}</section>`;else if(route.startsWith('tracking:'))content=tracking(route.split(':')[1]);else if(route==='activity')content=title('Every point, explained.','Your rewards and purchase points in one place.')+`<div class="card soft mt"><h3>${state.points} available · ${state.pending} pending</h3></div><section class="section">${state.activity.map(x=>`<div class="activity"><div>${esc(x.title)}<small>${x.status==='pending'?'Pending · 30-day waiting period':'Available / processed'}</small></div><b>${x.points>0?'+':''}${x.points} pts</b></div>`).join('')}</section>`;else if(route==='inbox')content=title('You’re in the loop.','Updates about your auctions, orders and rewards.')+`<section class="section">${state.notices.length?state.notices.map(n=>btn(`<h3>${esc(n.title)}</h3><p>${esc(n.detail)}</p>`,`go:${n.route}`,'inbox-card')).join(''):empty('bell','All caught up.','Auction and order updates will appear here.',btn('Explore auctions','go:auctions','secondary'))}</section>`;else if(route.startsWith('ticket:')){const t=state.tickets.find(t=>t.id===route.split(':')[1]);content=t?`${title('We have your request.')}<div class="notice"><b>${t.id} · Submitted</b><p>${t.priority?'Priority member route':'Standard member route'}</p></div><div class="card"><h3>${esc(t.topic)}</h3><p class="small mt">${esc(t.message)}</p>${t.order?`<p class="small mt">Related order: ${esc(t.order)}</p>`:''}</div><p class="small mt">Local demo request only. No message was sent and no response time is promised.</p>${btn('Back to support','go:support','primary full mt')}`:empty('support','Request not found','Return to Support to see your requests.',btn('Support','go:support'));}else content=offers();$('#main').innerHTML=content;save();}
function unlock(id){if(!state.member){pendingAuthRoute=route;navigate('login');return;}const p=prod(id);sheet('Your member offer',`<div class="row mb"><img src="assets/${p.image}" alt="${p.name}" width="75" height="75" style="object-fit:contain"><div><h3>${p.name}</h3><p class="price" style="color:var(--plum)">${money(p.price)}</p></div></div><div class="card soft"><span class="eyebrow">DEMO OFFER CODE</span><h2 class="mt">HOMEPLUS</h2>${btn('Copy code','copyoffer','text-btn mt')}</div><p class="mt">The offer is confirmed on the webshop. Reward vouchers are a separate discount choice.</p><a href="${p.url}" target="_blank" rel="noopener noreferrer" class="primary full mt" data-handoff="${id}">Continue to vidaXL webshop ${icon('external')}</a><details class="faq mt"><summary>Preview a completed order · demo</summary><p>Simulate the return after a purchase, without placing an order or making a payment.</p>${btn('Simulate confirmed order',`purchase:${id}`,'secondary full mt',state.purchases.includes('offer:'+id)?'disabled':'')}</details>`,'unlock');log('offer_unlocked');}
function bidReview(amount){const a=state.auction;sheet('Review your maximum bid',`<div class="card soft"><small>Your private maximum</small><h1 class="mt">${money(amount)}</h1><p class="small mt">Current highest bid: ${money(a.current)}</p></div><p class="mt">We’ll automatically bid only as much as needed, up to this limit. Winning triggers the order and payment process.</p><div class="card mt"><h3>Demo delivery & payment</h3><p class="small mt">Alex Morgan · Sample Netherlands address<br>Payment authorization is simulated. No payment details are collected.</p></div><label class="checks"><input id="bidagree" type="checkbox"><span>I confirm this demo bid and understand my maximum cannot be casually withdrawn in the real auction.</span></label>${btn('Confirm demo maximum',`confirmbid:${amount}`,'primary full','id="confirmbid" disabled')}<p class="small mt">No real bid or payment will be submitted.</p>`,'bidreview');}
function rewardSheet(){if(state.coupon&&!state.coupon.used){sheet('Your reward is ready',`<div class="success-icon">${icon('gift')}</div><div class="success"><h2>${money(state.coupon.value)} reward voucher</h2><p>${state.coupon.points} points exchanged for a demo voucher.</p></div><div class="card soft"><h3>${state.coupon.code}</h3><p class="small mt">Use as a separate discount choice. Cannot be combined with member-offer discounts.</p></div>${btn('Copy voucher','copyvoucher','secondary full mt')}${btn('Explore eligible products','voucherproducts','primary full')}`,'voucher');return;}sheet('Turn points into a little extra',`<p>Choose your reward. You have <b>${state.points} available points</b>.</p><div class="voucher-options">${[5,10,20,40].map(n=>btn(`<b>${money(n*.5)}</b><small>${n} points</small>`,`selectvoucher:${n}`,voucher===n?'selected':'',state.points<n?'disabled':'')).join('')}</div><p class="small">Reward discounts cannot be combined with other discounts. Vouchers shown here are demo values.</p>${btn(`Use ${voucher} points`,`redeem:${voucher}`,'primary full',state.points<voucher?'disabled':'')}`,'redeem');}
function demo(){sheet('Explore the concept',`<p>Use sample personas and controlled events to preview the complete experience. Prices, tiers, missions, bids and support are illustrative. No transactions or messages are sent.</p><div class="demo-controls mt">${btn('Preview Silver membership','persona:Silver','secondary')}${btn('Preview Gold & priority support','persona:Gold','secondary')}${btn('See the motion tour','motiontour','secondary')}${btn('Preview Splash','go:splash','secondary')}${btn('Preview Login','go:login','secondary')}${btn('Preview Registration','go:register','secondary')}${btn('Preview first-time member setup','firsttime','secondary')}${btn('Drop a saved / viewed product price','priceevent','secondary')}${btn('Show a related auction alert','auctionevent','secondary')}${btn('Advance discovery streak by one day','nextday','secondary')}${btn('Advance purchase points past waiting period','release','secondary')}${btn('Approve pending UGC submission','approveugc','secondary',!state.ugcPending?'disabled':'')}${btn('Preview a competing auction bid','democompete','secondary')}${btn('Close the current auction','democlose','secondary')}${btn('Restart auction','demorestart','secondary')}${btn('Reset complete demo','reset','secondary')}</div><p class="small mt">Brand foundation: live vidaXL logo, store plum / lemon / neutral colors and system-font stack. Final brand approval and native design guidance remain to be confirmed.</p>`,'demo');}
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');const hand=e.target.closest('[data-handoff]');if(hand)log('webshop_handoff_started');if(!b)return;const action=b.dataset.action;if(action==='backdrop'){if(e.target===b)dismiss();return;}if(action.startsWith('go:')){navigate(action.slice(3));return;}if(action.startsWith('save:')){const id=action.slice(5);const wasSaved=state.saved.includes(id);state.saved=wasSaved?state.saved.filter(x=>x!==id):[...state.saved,id];if(!wasSaved)state.priceBaselines[id]=prod(id).price;else delete state.priceBaselines[id];save();render();if(!wasSaved)document.querySelectorAll('[data-action="save:'+id+'"]').forEach(x=>x.classList.add('heart-pop'));toast(state.saved.includes(id)?'Saved to your offers':'Removed from saved offers');return;}if(action.startsWith('category:')){category=action.slice(9);if(category!=='All'&&!state.categories.includes(category))state.categories.push(category);render();return;}if(action.startsWith('afilter:')){auctionFilter=action.slice(8);render();return;}if(action.startsWith('unlock:')){unlock(action.slice(7));return;}if(action.startsWith('watch:')){const id=action.slice(6);state.watched=state.watched.includes(id)?state.watched.filter(x=>x!==id):[...state.watched,id];render();toast(state.watched.includes(id)?'Added to your watchlist':'Removed from your watchlist');return;}if(action.startsWith('confirmbid:')){const n=Number(action.split(':')[1]);state.auction.authorized=true;const result=placeBid(state,n);if(!result.ok){dismiss();error=result.message;render();return;}log('bid_accepted');dismiss();render();toast('Maximum confirmed. You’re leading.');return;}if(action.startsWith('claim:')){const id=action.split(':')[1];if(claim(state,id)){log('reward_claimed');render();sheet('A little win, all yours.',`<div class="success confetti"><div class="success-icon">${icon('spark')}</div><h2>+${missions.find(m=>m.id===id).points} points unlocked.</h2><p>Your completed mission has been added to your available balance.</p></div>${btn('Keep exploring','dismiss','primary full')}`,'claimed');}return;}if(action.startsWith('purchase:')){const o=purchase(state,action.split(':')[1]);if(o){log('order_confirmed');render();sheet('Your demo order is confirmed',`<div class="success"><div class="success-icon">${icon('check')}</div><h2>Something good is on its way.</h2><p>${o.id} · ${money(o.amount)}</p></div><div class="card soft"><h3>+${o.points} purchase points pending</h3><p class="small mt">Available after the waiting period, subject to the programme rules.</p></div>${btn('View your order',`go:tracking:${o.id}`,'primary full')}${btn('Explore rewards','go:rewards','secondary full mt')}`,'purchased');}else toast('This demo purchase is already confirmed.');return;}if(action.startsWith('selectvoucher:')){voucher=Number(action.split(':')[1]);rewardSheet();return;}if(action.startsWith('redeem:')){if(redeem(state,Number(action.split(':')[1]))){log('points_redeemed');render();rewardSheet();}return;}if(action.startsWith('orderhelp:')){supportForm.order=action.split(':')[1];navigate('supportform');return;}if(action.startsWith('persona:')){state=freshState();hydrate(state);state.member=true;state.name='Alex';state.tier=action.split(':')[1];state.tierProgress=state.tier==='Gold'?120:40;state.points=state.tier==='Gold'?120:40;if(state.tier==='Gold')state.activity=[{title:'Available purchase rewards',points:120,status:'available'},{title:'Recent purchase',points:12,status:'pending'}];save();navigate('rewards');toast('Demo persona: '+state.tier+' member');return;}
switch(action){case'dismiss':dismiss();break;case'back':navigate(trail.pop()||'offers',false);break;case'scrolloffers':$('#offers-section')?.scrollIntoView({behavior:'smooth',block:'start'});break;case'clearsearch':query='';category='All';render();break;case'demo':demo();break;case'member':state=freshState();hydrate(state);state.member=true;state.name='Alex';navigate(pendingAuthRoute);pendingAuthRoute='home';break;case'signout':state=freshState();hydrate(state);state.member=false;state.chatMessages=[];navigate('login');break;case'firsttime':state.member=false;navigate('register');break;case'notifications':state.notifications=!state.notifications;render();toast(state.notifications?'In-app auction alerts enabled':'Auction alerts switched off');break;case'compete':case'democompete':{const r=compete(state);if(!r){toast('Place a demo bid first.');break;}log('competing_bid');navigate('auction');toast(r==='automatic'?'Automatic bid placed within your limit.':'Your maximum has been exceeded.');break;}case'closeauction':case'democlose':closeAuction(state);log('auction_closed');navigate('auction');break;case'restartauction':case'demorestart':state.auction=freshState().auction;save();navigate('auction');toast('A fresh demo auction is ready.');break;case'nextday':state.streak=Math.min(3,state.streak+1);save();navigate('rewards');toast('Discovery streak updated for the demo.');break;case'release':releasePoints(state);save();navigate('rewards');toast('Demo waiting period complete. Points updated.');break;case'reset':state=freshState();hydrate(state);category='All';auctionFilter='Live';save();navigate('splash');toast('The demo is ready to explore again.');break;case'copyoffer':case'copyvoucher':try{await navigator.clipboard.writeText(action==='copyoffer'?'HOMEPLUS':state.coupon.code);toast('Demo code copied');}catch{toast('Code: '+(action==='copyoffer'?'HOMEPLUS':state.coupon.code));}break;case'voucherproducts':sheet('Choose a reward purchase',`<p>Preview your voucher on a regular-price product. Member-offer discounts are not combined.</p><div class="stack mt">${products.map(p=>btn(`<div class="row"><img src="assets/${p.image}" alt="" width="55" height="55" style="object-fit:contain"><div><h3>${p.name}</h3><p class="small">${money(Math.max(0,p.original-state.coupon.value))} after ${money(state.coupon.value)} voucher</p></div></div>`,`voucherbuy:${p.id}`,'secondary','')).join('')}</div>`,'voucherproducts');break;case'approveugc':if(state.ugcPending&&!state.ugcApproved){state.ugcPending=false;state.ugcApproved=true;state.points+=5;state.tierProgress+=5;if(state.tierProgress>=100)state.tier='Gold';state.activity.unshift({title:'Approved home photo',points:5,status:'available'});save();navigate('rewards');toast('Photo approved in the demo. +5 points credited.');}break;case'pending':sheet('Purchase points take a little time',`<p>You have <b>${state.pending} pending points</b>.</p><div class="card soft mt"><h3>Why the waiting period?</h3><p class="small mt">Purchase points become available after the 30-day waiting period. Cancelled or returned purchases can affect earned points.</p></div><p class="small mt">Available points can be exchanged for rewards now. Pending points are shown separately so your balance stays clear.</p>${btn('View point activity','go:activity','primary full')}`,'pending');break;case'badges':sheet('Your home explorer badges',`<div class="stack"><div class="card ${state.profileDone?'soft':''}"><h3>${state.profileDone?'✓':'○'} Made it yours</h3><p class="small mt">Complete your home preferences.</p></div><div class="card ${state.claims.includes('explore')?'soft':''}"><h3>${state.claims.includes('explore')?'✓':'○'} Thoughtful finder</h3><p class="small mt">Complete your exploration mission.</p></div><div class="card ${state.streak>=3?'soft':''}"><h3>${state.streak>=3?'✓':'○'} Home explorer</h3><p class="small mt">Explore on 3 days in a week. No purchase needed.</p></div></div><p class="small mt">Illustrative gamification. Badges don’t change purchase obligations or bidding rules.</p>`,'badges');break;case'benefits':sheet('More from your membership',`<div class="stack"><div class="card"><h3>Silver · discover more</h3><p class="small mt">Member offers, rewards, missions and standard support.</p></div><div class="card soft"><h3>Gold · a little extra</h3><p class="small mt">The same essentials, plus priority support. Demo threshold: 100 progress points.</p></div></div><p class="small mt">Tier progress and available points are separate. Spending points doesn’t reduce earned tier progress. Tiers and thresholds are illustrative and need client approval.</p>`,'benefits');break;case'howauction':sheet('Your limit. Smarter bidding.',`<div class="stack"><div class="card"><h3>1. Get ready</h3><p class="small mt">Confirm delivery and payment authorization before bidding.</p></div><div class="card"><h3>2. Set your private maximum</h3><p class="small mt">We bid in increments only as needed, up to your limit.</p></div><div class="card"><h3>3. Stay in the loop</h3><p class="small mt">Watch your position. Late bids can extend the closing time.</p></div></div>${btn('Explore the auction','go:auction','primary full')}`,'howauction');break;default:if(action.startsWith('voucherbuy:')){const id=action.split(':')[1],p=prod(id);if(!state.coupon||state.coupon.used){toast('Your voucher has already been used.');break;}const o=purchase(state,id,'voucher',Math.max(0,p.original-state.coupon.value));if(o){state.coupon.used=true;save();navigate('orders');toast('Demo voucher applied to a regular-price purchase.');}else toast('That demo voucher purchase is already confirmed.');}}
});
document.addEventListener('input',e=>{if(e.target.id==='search'){query=e.target.value;$('#offer-results').innerHTML=offerResults();clearTimeout(searchTimer);searchTimer=setTimeout(()=>{if(recordSearch(state,query))save();},650);}if(e.target.id==='bidagree')$('#confirmbid').disabled=!e.target.checked;});
document.addEventListener('change',e=>{if(e.target.id==='bidagree')$('#confirmbid').disabled=!e.target.checked;if(e.target.name==='photo'){const f=e.target.files[0];if(!f)return;if(f.size>5*1024*1024||!['image/jpeg','image/png','image/webp'].includes(f.type)){e.target.value='';toast('Choose a JPG, PNG or WebP under 5 MB.');return;}if(ugcPhoto)URL.revokeObjectURL(ugcPhoto);ugcPhoto=URL.createObjectURL(f);$('#photo-preview').innerHTML=`<img class="photo-preview" src="${ugcPhoto}" alt="Your selected photo preview">`;}});
document.addEventListener('submit',e=>{e.preventDefault();const f=e.target,d=new FormData(f);if(!f.checkValidity()){f.reportValidity();return;}if(f.id==='bid-form'){const n=Number(d.get('bid'));if(!state.member){pendingAuthRoute=route;navigate('login');return;}if(!Number.isFinite(n)||n<Math.max(state.auction.current+1,state.auction.max+1)){error='Choose a maximum above the current bid and your previous limit.';render();return;}bidReview(n);}else if(f.id==='preferences-form'){state.name=String(d.get('name')).trim()||'Alex';state.preferences={project:d.get('project'),style:d.get('style')};state.profileDone=true;save();navigate('rewards');toast('Preferences saved. Your mission reward is ready to claim.');}else if(f.id==='join-form'){state=freshState();state.name=String(d.get('name')).trim()||'Alex';state.points=0;state.pending=0;state.tierProgress=0;state.activity=[];state.orders=[];state.orderStreak=0;save();navigate('offers');toast('Welcome, '+state.name+'. Your demo membership is ready.');}else if(f.id==='ugc-form'){state.ugcPending=true;save();navigate('rewards');toast('Demo submission saved for review. Points are not credited yet.');}else if(f.id==='support-form'){const msg=String(d.get('message')).trim();if(msg.length<10){toast('Add at least 10 characters to your message.');return;}const t={id:'HC-'+(1042+state.tickets.length),topic:d.get('topic'),order:d.get('order'),message:msg,priority:state.tier==='Gold'};state.tickets.unshift(t);supportForm.order='';log('support_requested');navigate('ticket:'+t.id);}});
setInterval(()=>{if(!['won','lost'].includes(state.auction.status)&&Date.now()>=state.auction.end){closeAuction(state);save();if(['auction','auctions'].includes(route)&&!modal)render();}document.querySelectorAll('[data-clock]').forEach(el=>el.textContent=clock());},1000);

// Expanded mobile UX concept. The preview uses deterministic local adapters;
// Flutter/Firebase implementation contracts are documented separately.
function header(){
 if(['splash','login','register','join','verify','forgot'].includes(route)){$('#header').innerHTML='';return;}
 const root=['home','products','offers','auctions','rewards','chat'].includes(route);
 const names={auction:'Auction details',saved:'Your wishlist',orders:'Your orders',profile:'Your account',preferences:'Home preferences',ugc:'Share your home',inbox:'Your updates',activity:'Point activity',support:'Member support',supportform:'Contact support',settings:'Your preferences'};
 $('#header').innerHTML=`<div class="topbar">${root?`<button class="brand brand-btn" data-action="go:home" aria-label="vidaXL Plus Home"><img src="assets/logo.svg" alt="vidaXL"><span class="plus">+</span></button>`:`<div class="backtitle">${btn(icon('back'),'back','icon-btn','aria-label="Go back"')}<h2>${names[route]||(route.startsWith('offer:')?'Product details':route.startsWith('tracking:')?'Order details':'vidaXL+')}</h2></div>`}<div class="header-actions">${btn(icon('bell')+(state.notices.some(n=>!n.read)?'<span class="dot"></span>':''),'go:inbox','icon-btn','aria-label="Notifications"')}${btn(esc(state.member?state.name.slice(0,1).toUpperCase():'?'),'go:profile','icon-btn avatar','aria-label="Your account"')}</div></div>`;
}
function navigation(){
 if(['splash','login','register','join','verify','forgot'].includes(route)){$('#nav').innerHTML='';return;}
 const tab=route==='home'?'home':route.startsWith('offer')||['products','saved'].includes(route)?'products':['auction','auctions'].includes(route)?'auctions':['rewards','preferences','ugc','activity'].includes(route)?'rewards':route==='chat'?'chat':'';
 $('#nav').innerHTML=`<div class="nav">${[['home','home','Home'],['products','tag','Shop'],['auctions','hammer','Auctions'],['rewards','gift','Rewards'],['chat','chat','Ask vida']].map(([r,i,l])=>btn(`<span class="navicon">${icon(i)}</span>${l}`,`go:${r}`,tab===r?'active':'',tab===r?'aria-current="page"':'')).join('')}</div>`;
}
paths.home='m3 10 9-7 9 7v11h-7v-7h-4v7H3V10';paths.chat='M21 11a9 9 0 0 1-9 9H4l-2 2v-10a10 10 0 0 1 19-1 M7 10h10 M7 14h7';paths.filter='M4 7h16 M7 12h10 M10 17h4';paths.lock='M5 10h14v12H5V10 M8 10V6a4 4 0 0 1 8 0v4 M12 15v3';
function productCard(p){p=prod(p.id);const reduced=state.priceOverrides[p.id]!=null;return `<article class="product"><div class="product-photo">${btn(`<img src="assets/${p.image}" alt="${p.name}" loading="lazy" style="view-transition-name:product-${p.id}">`,`go:offer:${p.id}`,'','aria-label="View '+p.name+'"')}${btn(icon('heart'),`save:${p.id}`,'icon-btn save '+(state.saved.includes(p.id)?'is-saved':''),`aria-label="${state.saved.includes(p.id)?'Unsave':'Save'} ${p.name}" aria-pressed="${state.saved.includes(p.id)}"`)}${reduced?'<span class="photo-badge">Price dropped</span>':''}</div><div class="product-label">${reduced?'A LITTLE LESS TODAY':p.category}</div><button class="product-name" data-action="go:offer:${p.id}">${p.name}</button><div class="price">${money(p.price)} <del>${money(p.original)}</del></div><div class="earn">Member price · ${p.points} purchase points</div></article>`;}
function offers(){return shopPage();}
function shopPage(){const rows=searchProducts(state,query,category);if(shopSort==='low')rows.sort((a,b)=>a.price-b.price);if(shopSort==='high')rows.sort((a,b)=>b.price-a.price);return `<div class="page-kicker">THOUGHTFUL FINDS. MEMBER PRICES.</div>${title('A little more for your home.')}<form id="search-form" class="search">${icon('search')}<input id="search" type="search" placeholder="Search sofas, garden, curtains…" aria-label="Search products" value="${esc(query)}"><button class="search-submit" type="submit" aria-label="Search">${icon('arrow')}</button></form><div class="categories">${['All','Garden','Furniture','Bedroom'].map(c=>btn(c,`category:${c}`,'chip '+(category===c?'active':''))).join('')}</div><div class="section-head"><span class="small">${rows.length} sample finds</span><label class="sort-label">Sort <select id="shop-sort" aria-label="Sort products"><option value="recommended" ${shopSort==='recommended'?'selected':''}>Recommended</option><option value="low" ${shopSort==='low'?'selected':''}>Price: low to high</option><option value="high" ${shopSort==='high'?'selected':''}>Price: high to low</option></select></label></div><div id="offer-results">${rows.length?`<div class="product-grid">${rows.map(productCard).join('')}</div>`:empty('search','Let’s try something else.','Search another category or clear your filters.',btn('Clear filters','clearsearch','secondary'))}</div><div class="brand-trust section"><span>${icon('tag')}Member value</span><span>${icon('heart')}Save your favourites</span></div>`;}
function homePage(){const feed=recommendations(state),recent=state.viewHistory.slice(0,4),updates=state.notices.filter(n=>!n.read).slice(0,2);const recommended=feed.rows.slice(0,2);return `<div class="home-greeting"><div><span class="greeting">${state.member?'Good to see you, '+esc(state.name):'Welcome to vidaXL+'}</span><h1>Your home.<br>Your kind of more.</h1></div><button class="membership-orb" data-action="${state.member?'go:rewards':'go:login'}">${icon('spark')}<strong>${state.member?state.points:'+'}</strong><small>${state.member?'points':'Join us'}</small></button></div><button class="search home-search full" data-action="go:products" aria-label="Search products">${icon('search')}<span>What’s your next home project?</span><span class="search-arrow">${icon('arrow')}</span></button>${updates.length?`<section class="updates-strip"><div class="section-head"><h2>Worth a little look</h2>${btn('All updates','go:inbox','text-btn')}</div>${updates.map(n=>`<button class="update-compact" data-action="go:${n.route}"><span class="update-symbol">${icon(n.type==='prices'?'tag':n.route==='auction'?'hammer':'bell')}</span><span><b>${esc(n.title)}</b><small>${esc(n.detail)}</small></span>${icon('chevron')}</button>`).join('')}</section>`:''}<section class="editorial-hero"><img src="assets/bedroom.jpg" alt="A vidaXL bedroom with natural textures"><div class="editorial-caption"><span class="eyebrow">THE HOME EDIT</span><h2>Small changes.<br>A whole new feeling.</h2><button data-action="shopcategory:Bedroom" aria-label="Explore bedroom finds">${icon('arrow')}</button></div></section><div class="room-shortcuts">${[['Garden','garden.jpg'],['Furniture','chair.jpg'],['Bedroom','bedroom.jpg']].map(([c,img])=>`<button data-action="shopcategory:${c}"><span><img src="assets/${img}" alt=""></span>${c}</button>`).join('')}<button data-action="go:products"><span class="all-rooms">${icon('tag')}</span>All finds</button></div><section class="section"><div class="section-head"><div><span class="page-kicker">${feed.interest?'INSPIRED BY YOU':'MEMBER FAVOURITES'}</span><h2>${feed.interest?feed.interest+' finds, picked for you':'Find your next favourite'}</h2></div>${btn('See all','go:products','text-btn')}</div>${recommended.length?`<div class="product-grid">${recommended.map(r=>productCard(r.product)).join('')}</div><div class="feed-explanation">${icon('spark')}<span>${esc(recommended[0].reason)}</span>${btn('Why?','whyfeed','text-btn')}</div>`:empty('heart','A fresh start for your feed','Reset hidden recommendations in your preferences.',btn('Preferences','go:settings','secondary'))}</section>${recent.length?`<section class="section"><div class="section-head"><h2>Still on your mind?</h2>${btn('Clear','clearviews','text-btn')}</div><div class="recent-rail">${recent.map(v=>{const p=prod(v.id);return `<button data-action="go:offer:${p.id}"><img src="assets/${p.image}" alt="${p.name}"><b>${p.name}</b><span>${money(p.price)}</span></button>`;}).join('')}</div></section>`:''}<section class="section auction-teaser"><div class="row spread"><span class="eyebrow">LIVE DISCOVERIES</span><span class="pill ${state.auction.status==='outbid'?'red':'green'}">${auctionStatus()}</span></div><div class="row mt"><img src="assets/bench.jpg" alt="Garden bench"><div><h2>A little spot<br>in the sun.</h2><p class="small mt">${['won','lost'].includes(state.auction.status)?'See the auction outcome':'Current bid '+money(state.auction.current)}</p></div></div>${btn('Explore the auction '+icon('arrow'),'go:auction','secondary full mt')}</section><section class="section next-win"><span class="reward-spark">${icon('spark')}</span><div><span class="page-kicker">YOUR NEXT LITTLE WIN</span><h3>${state.member?state.claims.length+' of 3 missions completed':'More to love with membership'}</h3><p class="small">Discover, complete, celebrate.</p></div>${btn(icon('arrow'),'go:rewards','icon-btn','aria-label="Explore rewards"')}</section><section class="section assistant-invite"><div class="row"><span class="task-icon">${icon('chat')}</span><div><h3>A little help finding your style?</h3><p class="small">Ask vida about your space or budget.</p></div></div>${btn('Let’s find something you’ll love','go:chat','text-btn mt')}</section>`;}
function offerDetail(id){if(!galleryFor(id).length)return empty('box','This product is unavailable.','Return to Shop to explore current sample products.',btn('Browse products','go:products'));const p=prod(id);let body=offerDetailLegacy(id);const start=body.indexOf('<div class="image-large">'),end=body.indexOf('</div>',start)+6;body=body.slice(0,start)+productGallery(id)+body.slice(end);body=body.replace('<section class="section"><h2>Good to know</h2>',`<button class="context-ai full" data-action="askproduct:${p.id}">${icon('chat')}<span><b>Want a little help choosing?</b><small>Ask vida about this product</small></span>${icon('chevron')}</button><section class="section"><h2>Good to know</h2>`);return body;}

function authShell(content){return `<div class="auth-brand"><img src="assets/logo.svg" alt="vidaXL"><span>+</span></div>${content}`;}
function splashPage(){return `<section class="splash splash-premium"><div class="splash-halo"></div><div class="splash-scene splash-scene-one"><img src="assets/bedroom.jpg" alt="vidaXL bedroom inspiration"></div><div class="splash-scene splash-scene-two"><img src="assets/garden.jpg" alt="vidaXL garden inspiration"></div><span class="splash-star star-one">✦</span><span class="splash-star star-two">✦</span><div class="splash-mark"><img src="assets/logo.svg" alt="vidaXL"><span>+</span></div><div class="splash-copy"><span class="eyebrow">LIVE IT UP FOR LESS</span><h1>A little more home.<br>A little more you.</h1><p>Thoughtful finds. Little rewards.<br>Made for the way you live.</p></div><div class="splash-benefits"><span>Discover</span><i>·</i><span>Bid</span><i>·</i><span>Earn</span></div><div class="splash-progress"><span></span></div>${btn('Enter the experience '+icon('arrow'),'skipsplash','primary splash-enter')}<small class="splash-footnote">Your next good find starts here.</small></section>`;}

function loginPage(){return authShell(`<span class="page-kicker">WELCOME BACK</span>${title('Your next good find<br>starts here.','Sign in to your vidaXL+ membership.')}<form id="login-form" class="auth-form"><label class="field"><span>Email address</span><input name="email" type="email" autocomplete="off" placeholder="alex@example.com" required></label><label class="field"><span>Password</span><div class="password-field"><input name="password" type="password" autocomplete="off" minlength="8" placeholder="Sample password · 8+ characters" required>${btn(icon('eye'),'togglepassword','icon-btn','aria-label="Show password"')}</div></label><div class="row spread"><small>Use sample information</small>${btn('Forgot password?','go:forgot','text-btn')}</div><p class="error" id="auth-error" role="alert"></p><button class="primary full mt" type="submit">Sign in ${icon('arrow')}</button></form><div class="auth-divider"><span>or explore the concept</span></div>${btn('Continue with demo account','member','secondary full')}<p class="auth-footer">New to vidaXL+? ${btn('Create an account','go:register','text-btn')}</p>${btn('Browse before joining','guest','text-btn full')}<p class="prototype-note">Concept sign-in only. No real credentials are authenticated or stored.</p>`);}
function join(){return registrationPage();}
function registrationPage(){return authShell(`<span class="page-kicker">MAKE YOURSELF AT HOME</span>${title('A little more,<br>just for you.','Join for member offers, rewards and discoveries.')}<form id="register-form" class="auth-form"><label class="field"><span>First name</span><input name="name" required maxlength="30" placeholder="Alex" autocomplete="off"></label><label class="field"><span>Email address</span><input name="email" type="email" required placeholder="alex@example.com" autocomplete="off"></label><label class="field"><span>Create a password</span><div class="password-field"><input name="password" type="password" minlength="8" required placeholder="Sample password · 8+ characters" autocomplete="off">${btn(icon('eye'),'togglepassword','icon-btn','aria-label="Show password"')}</div><span class="help">Use sample data. Passwords are discarded by this prototype.</span></label><label class="checks"><input name="terms" type="checkbox" required><span>I agree to the sample membership terms and understand this is a concept.</span></label><label class="checks"><input name="marketing" type="checkbox"><span>Preview opting into member offers by email. Optional; no emails are sent.</span></label><p class="error" id="auth-error" role="alert"></p><button class="primary full" type="submit">Create demo account ${icon('arrow')}</button></form><p class="auth-footer">Already a member? ${btn('Sign in','go:login','text-btn')}</p><p class="prototype-note">No real account is created. Production authentication is planned with Firebase.</p>`);}
function verifyPage(){return authShell(`<div class="success-icon">${icon('check')}</div><span class="page-kicker">ONE LAST LITTLE STEP</span>${title('Let’s make it yours.','Your sample membership is ready.')}<div class="card soft mt"><h3>Email verification</h3><p class="small mt">The Flutter app will send a verification email. Here, preview a verified account without sending anything.</p></div>${btn('Verify demo account & continue','verifyaccount','primary full section')}${btn('Back to sign in','go:login','text-btn full mt')}`);}
function forgotPage(){return authShell(`<span class="page-kicker">LET’S GET YOU BACK IN</span>${title('Forgot your password?','We’ll help you get back to your good finds.')}<form id="forgot-form" class="auth-form"><label class="field"><span>Email address</span><input name="email" type="email" required placeholder="alex@example.com" autocomplete="off"></label><button class="primary full mt" type="submit">Preview reset request</button></form><p class="prototype-note">No email is sent. Production will use Firebase password reset.</p>${btn('Back to sign in','go:login','text-btn full mt')}`);}
function notificationPage(){hydrate(state);const rows=state.notices.map((n,i)=>({...n,index:i})).filter(n=>notificationFilter==='All'||notificationFilter==='Unread'&&!n.read||notificationFilter==='Prices'&&n.type==='prices'||notificationFilter==='Auctions'&&(n.type==='auctions'||n.route==='auction'));return `<div class="row spread">${title('Your little updates.')}<button class="text-btn" data-action="readall">Read all</button></div><p class="subtitle">Good news, useful reminders and things you’re watching.</p><div class="categories mt">${['All','Unread','Prices','Auctions'].map(f=>btn(f,`nfilter:${f}`,'chip '+(notificationFilter===f?'active':''))).join('')}</div>${rows.length?rows.map(n=>`<button class="notification-row ${n.read?'':'unread'}" data-action="notice:${n.index}"><span class="notification-symbol">${icon(n.type==='prices'?'tag':n.route==='auction'?'hammer':n.route==='orders'?'box':'gift')}</span><span><b>${esc(n.title)}</b><small>${esc(n.detail)}</small><em>${n.read?'Read':'New'} · Sample update</em></span>${icon('chevron')}</button>`).join(''):empty('bell','All caught up.','Save or watch a find to receive relevant updates.',btn('Explore products','go:products','secondary'))}${btn('Manage alert preferences','go:settings','text-btn section')}`;}
function settingsPage(){return `${title('Make it work for you.','Choose what feels useful. You’re in control.')}<section class="section">${[['prices','Wishlist & related price drops'],['auctions','Watched & related auction updates'],['rewards','Rewards and membership updates']].map(([k,l])=>`<div class="menu-row"><span>${l}</span><button class="toggle ${state.alertPrefs[k]?'on':''} end" data-action="alertpref:${k}" role="switch" aria-checked="${state.alertPrefs[k]}" aria-label="${l}"></button></div>`).join('')}<div class="menu-row">Personalized recommendations<button class="toggle ${state.personalization?'on':''} end" data-action="personalization" role="switch" aria-checked="${state.personalization}" aria-label="Personalized recommendations"></button></div><p class="small mt">The demo uses searches, viewed products and saved items in this browser. Turning personalization off restores general member picks.</p>${btn('Clear search & viewing history','clearhistory','secondary full mt')}${btn('Restore hidden recommendations','restorehidden','secondary full mt')}</section>`;}
function profile(){let body=profileLegacy();body=body.replace("<div class=\"menu-row\">",`${btn(`${icon('settings')}Preferences & alerts<span class="end">${icon('chevron')}</span>`,'go:settings','menu-row')}${btn(`${icon('support')}Member support<span class="end">${icon('chevron')}</span>`,'go:support','menu-row')}<div class="menu-row">`);return body;}
function chatPage(){const context=chatContext&&prod(chatContext);return `<div class="chat-heading"><span class="assistant-avatar">${icon('spark')}</span><div><h1>A little help.<br>A better find.</h1><p class="small">Ask vida · shopping assistant concept</p></div></div>${context?`<div class="chat-context"><img src="assets/${context.image}" alt=""><span>Chatting about <b>${context.name}</b></span>${btn(icon('close'),'clearcontext','icon-btn','aria-label="Clear product context"')}</div>`:''}<div class="chat-disclosure">Responses are simulated from the sample catalogue. Live AI is planned for Flutter/Firebase.</div><div class="chat-suggestions">${['Garden ideas under €200','Explain my rewards','How does bidding work?'].map(q=>btn(q,`prompt:${q}`,'chip')).join('')}</div><section id="chat-messages" class="chat-messages" aria-label="Conversation" aria-live="polite">${state.chatMessages.length?state.chatMessages.map(chatBubble).join(''):`<div class="chat-bubble assistant"><p>Hi${state.member?', '+esc(state.name):''}! Tell me about your room, style or budget. I can help you explore finds, understand rewards or reach support.</p></div>`}${chatBusy?'<div class="typing-indicator" role="status" aria-label="Preparing response"><span></span><span></span><span></span></div>':''}</section><form id="chat-form" class="chat-composer"><label class="sr-only" for="chat-input">Message to Ask vida</label><input id="chat-input" name="message" placeholder="Ask about your next home project…" maxlength="500" required autocomplete="off"><button class="primary" aria-label="Send message" ${chatBusy?'disabled':''}>${icon('arrow')}</button></form><button class="text-btn full mt" data-action="go:support">Need a person? Open member support</button>`;}
function chatBubble(m){return `<article class="chat-bubble ${m.role}"><span class="chat-role">${m.role==='user'?'You':'Ask vida'}</span><p>${esc(m.text)}</p>${m.productIds?.length?`<div class="chat-products">${m.productIds.map(id=>{const p=prod(id);return `<button data-action="go:offer:${id}"><img src="assets/${p.image}" alt="${p.name}"><span><b>${p.name}</b><small>${money(p.price)} · sample member price</small></span>${icon('chevron')}</button>`;}).join('')}</div>`:''}${m.route?btn(m.cta,`go:${m.route}`,'text-btn mt'):''}</article>`;}
function render(){
 hydrate(state);header();navigation();document.querySelector('.app-frame')?.classList.toggle('entry-screen',['splash','login','register','join','verify','forgot'].includes(route));
 const extra={home:homePage,products:shopPage,splash:splashPage,login:loginPage,register:registrationPage,verify:verifyPage,forgot:forgotPage,chat:chatPage,inbox:notificationPage,settings:settingsPage};
 if(extra[route]){$('#main').innerHTML=extra[route]();save();}else renderLegacy();mountGallery();enhanceMotion();mountProductAction();if(lastRenderedRoute!==route){$('#main').classList.remove('route-enter');void $('#main').offsetWidth;$('#main').classList.add('route-enter');lastRenderedRoute=route;}
 if(route==='splash'){clearTimeout(splashTimer);splashTimer=setTimeout(()=>{if(route==='splash')navigate(state.member?'home':'login',false);},3400);}
}
function sendChat(text){const value=String(text).trim().slice(0,500);if(!value||chatBusy)return;state.chatMessages.push({role:'user',text:value,at:Date.now()});recordSearch(state,value);chatBusy=true;render();setTimeout(()=>{state.chatMessages.push(assistantReply(state,value,chatContext));chatBusy=false;save();if(route==='chat'){render();$('#chat-input')?.focus({preventScroll:true});$('#chat-messages')?.scrollIntoView({block:'end',behavior:'smooth'});}},650);}
document.addEventListener('click',e=>{
 const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action;
 if(!state.member&&(a.startsWith('claim:')||a==='redeem'||a.startsWith('purchase:'))){e.stopImmediatePropagation();pendingAuthRoute=route;navigate('login');return;}
 const handled=a==='skipsplash'||a==='motiontour'||a==='motionreward'||a==='zoomin'||a==='zoomout'||a==='zoomprev'||a==='zoomnext'||a.startsWith('gallery:')||a.startsWith('zoomgallery:')||a==='notifications'||a==='guest'||a==='togglepassword'||a==='verifyaccount'||a==='whyfeed'||a==='clearviews'||a==='clearhistory'||a==='restorehidden'||a==='personalization'||a==='readall'||a==='clearcontext'||a==='priceevent'||a==='auctionevent'||a.startsWith('shopcategory:')||a.startsWith('askproduct:')||a.startsWith('prompt:')||a.startsWith('nfilter:')||a.startsWith('notice:')||a.startsWith('alertpref:')||a.startsWith('hideproduct:');if(!handled)return;e.stopImmediatePropagation();
 if(a.startsWith('gallery:')){const [,id,n]=a.split(':');selectGallery(id,Number(n));}else if(a.startsWith('zoomgallery:')){openGalleryZoom(a.split(':')[1]);}else if(a.startsWith('shopcategory:')){category=a.split(':')[1];recordSearch(state,category);state.categories=[...new Set([...state.categories,category])];navigate('products');}
 else if(a.startsWith('askproduct:')){chatContext=a.split(':')[1];navigate('chat');}
 else if(a.startsWith('prompt:'))sendChat(a.slice(7));
 else if(a.startsWith('nfilter:')){notificationFilter=a.slice(8);render();}
 else if(a.startsWith('notice:')){const n=state.notices[Number(a.split(':')[1])];if(n){n.read=true;save();navigate(n.route);}}
 else if(a.startsWith('alertpref:')){const k=a.split(':')[1];state.alertPrefs[k]=!state.alertPrefs[k];if(k==='auctions')state.notifications=state.alertPrefs[k];render();}
 else if(a.startsWith('hideproduct:')){state.dismissedProducts=[...new Set([...state.dismissedProducts,a.split(':')[1]])];navigate('home');}
 else switch(a){case'skipsplash':clearTimeout(splashTimer);navigate(state.member?'home':'login');break;case'motiontour':motionTour();break;case'motionreward':sheet('A reward moment · motion preview',`<div class="success motion-reward"><div class="reward-orbit">${icon('spark')}</div><h2>A little win, all yours.</h2><p>+10 points celebration preview.</p><small>This preview doesn’t change your balance.</small></div>${btn('Replay celebration','motionreward','primary full')}`,'motionreward');burst();break;case'zoomin':setZoom(zoomScale+.5);break;case'zoomout':setZoom(zoomScale-.5);break;case'zoomprev':changeZoomImage(-1);break;case'zoomnext':changeZoomImage(1);break;case'notifications':state.notifications=!state.notifications;state.alertPrefs.auctions=state.notifications;render();toast(state.notifications?'Auction alerts enabled':'Auction alerts switched off');break;case'guest':state.member=false;navigate('home');break;case'togglepassword':{const input=b.parentElement.querySelector('input');input.type=input.type==='password'?'text':'password';b.setAttribute('aria-label',input.type==='password'?'Show password':'Hide password');break;}case'verifyaccount':state.member=true;navigate(pendingAuthRoute);pendingAuthRoute='home';toast('Your demo membership is ready.');break;case'clearcontext':chatContext=null;render();break;case'readall':state.notices.forEach(n=>n.read=true);render();toast('All updates marked as read');break;case'clearviews':state.viewHistory=[];render();toast('Recently viewed cleared');break;case'clearhistory':state.viewHistory=[];state.searchHistory=[];render();toast('Your discovery history is cleared');break;case'restorehidden':state.dismissedProducts=[];render();toast('Recommendations restored');break;case'personalization':state.personalization=!state.personalization;render();break;case'priceevent':{const id=state.saved[0]||state.viewHistory[0]?.id;if(!id){toast('Save or view a product first, then preview a price drop.');break;}dropPrice(state,id,Math.max(1,Math.round(prod(id).price*.9)));save();navigate('home');toast('Sample price drop applied. Check your updates.');break;}case'auctionevent':{const added=auctionDiscoveryAlert(state);save();navigate('home');toast(added?'Related auction update added.':'Explore or save a garden item first; duplicate updates are suppressed.');break;}case'whyfeed':{const feed=recommendations(state);sheet('Your feed, explained',`<p>${state.personalization?'We use your searches, viewed products and wishlist in this browser to choose relevant sample finds.':'Personalization is off. You’re seeing general member picks.'}</p><p class="small mt">Current interest: ${feed.interest??'still exploring'}. This is a transparent rule-based demo, not a trained recommendation model.</p><div class="stack mt">${feed.rows.slice(0,2).map(r=>btn('Show less of '+r.product.name,`hideproduct:${r.product.id}`,'secondary')).join('')}</div>${btn('Manage preferences','go:settings','primary full')}`,'whyfeed');break;}}
},true);
function productGallery(id){const images=galleryFor(id),selected=boundedIndex(gallerySelections[id]??0,images.length);gallerySelections[id]=selected;return `<section class="product-gallery" aria-label="${prod(id).name} image gallery"><div class="gallery-track" id="product-gallery-track" data-product="${id}">${images.map((im,i)=>`<button class="gallery-slide" data-action="zoomgallery:${id}" aria-label="Enlarge ${im.label}"><img src="assets/${im.src}" alt="${prod(id).name} — ${im.label}" ${i===0?'fetchpriority="high"':'loading="lazy"'}></button>`).join('')}</div><span class="gallery-count" id="gallery-count">${selected+1} / ${images.length}</span>${btn(icon('search'),'zoomgallery:'+id,'icon-btn gallery-expand','aria-label="Enlarge product image"')}<div class="gallery-caption"><span id="gallery-caption">${images[selected].label}</span><small>Swipe to explore</small></div><div class="gallery-thumbs">${images.map((im,i)=>btn(`<img src="assets/${im.src}" alt="${im.label}">`,`gallery:${id}:${i}`,'gallery-thumb '+(i===selected?'selected':''),`aria-label="Show ${im.label}" aria-pressed="${i===selected}"`)).join('')}</div></section>`;}
function selectGallery(id,n){const images=galleryFor(id);gallerySelections[id]=boundedIndex(n,images.length);const track=$('#product-gallery-track');track?.scrollTo?.({left:gallerySelections[id]*track.clientWidth,behavior:reducedMotion()?'instant':'smooth'});updateGalleryIndicators(id);}
function updateGalleryIndicators(id){const images=galleryFor(id),i=gallerySelections[id]??0;$('#gallery-count').textContent=`${i+1} / ${images.length}`;$('#gallery-caption').textContent=images[i].label;document.querySelectorAll('.gallery-thumb').forEach((b,n)=>{b.classList.toggle('selected',n===i);b.setAttribute('aria-pressed',String(n===i));});}
function mountGallery(){if(!route.startsWith('offer:'))return;const id=route.split(':')[1],track=$('#product-gallery-track');if(!track?.addEventListener)return;track.scrollLeft=(gallerySelections[id]??0)*track.clientWidth;track.addEventListener('scroll',()=>{const i=boundedIndex(Math.round(track.scrollLeft/Math.max(1,track.clientWidth)),galleryFor(id).length);if(i!==gallerySelections[id]){gallerySelections[id]=i;updateGalleryIndicators(id);}},{passive:true});}
function openGalleryZoom(id){zoomProduct=id;zoomScale=1;const images=galleryFor(id),i=gallerySelections[id]??0;sheet('A closer look',`<div class="zoom-stage"><img id="zoom-image" src="assets/${images[i].src}" alt="${prod(id).name} — ${images[i].label}"></div><p class="zoom-label">${images[i].label}</p><div class="zoom-toolbar">${btn(icon('back'),'zoomprev','icon-btn','aria-label="Previous image"')}${btn('−','zoomout','secondary','aria-label="Zoom out"')}<span id="zoom-level">100%</span>${btn('+','zoomin','secondary','aria-label="Zoom in"')}${btn(icon('chevron'),'zoomnext','icon-btn','aria-label="Next image"')}</div><p class="small">Zoom in, then scroll inside the image to inspect the detail.</p>`,'galleryzoom');}
function setZoom(n){zoomScale=boundedZoom(n);const img=$('#zoom-image');if(img){img.style.width=`${zoomScale*100}%`;img.style.maxWidth='none';}$('#zoom-level').textContent=Math.round(zoomScale*100)+'%';}
function changeZoomImage(delta){const images=galleryFor(zoomProduct);gallerySelections[zoomProduct]=((gallerySelections[zoomProduct]??0)+delta+images.length)%images.length;openGalleryZoom(zoomProduct);}
function reducedMotion(){return typeof matchMedia==='function'&&matchMedia('(prefers-reduced-motion: reduce)').matches;}
function burst(x,y){if(reducedMotion())return;const layer=$('#motion-layer');if(!layer)return;const width=typeof innerWidth==='number'?innerWidth:440,height=typeof innerHeight==='number'?innerHeight:800;layer.innerHTML=Array.from({length:16},(_,i)=>`<i class="motion-particle" style="left:${x??width/2}px;top:${y??height*.55}px;--dx:${Math.cos(i/16*Math.PI*2)*(50+i%3*22)}px;--dy:${Math.sin(i/16*Math.PI*2)*(50+i%3*22)}px;--turn:${i*47}deg;--delay:${i%3*25}ms;background:${i%2?'#93117e':'#f3d018'}"></i>`).join('');clearTimeout(motionTimer);motionTimer=setTimeout(()=>layer.innerHTML='',1000);}
function enhanceMotion(){if(revealObserver)revealObserver.disconnect();if(typeof IntersectionObserver==='function'){const observer=revealObserver=new IntersectionObserver(entries=>{entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('reveal-visible');observer.unobserve(e.target);}});},{threshold:.12});document.querySelectorAll('.editorial-hero,.auction-teaser,.next-win,.assistant-invite').forEach(el=>{el.classList.add('reveal-card');observer.observe(el);});}const count=$('[data-reward-count]');if(count&&typeof requestAnimationFrame==='function'&&!reducedMotion()){const final=Number(count.dataset.rewardCount),start=performance.now();const step=now=>{if(!count.isConnected)return;const t=Math.min(1,(now-start)/600);count.textContent=Math.round(final*(1-Math.pow(1-t,3)));if(t<1)requestAnimationFrame(step);};requestAnimationFrame(step);}}
function mountProductAction(){const slot=$('#product-action');if(!slot)return;if(!route.startsWith('offer:')||!galleryFor(route.split(':')[1]).length){slot.innerHTML='';return;}const p=prod(route.split(':')[1]);slot.innerHTML=`<div class="product-action-bar"><div><small>Member price</small><strong>${money(p.price)}</strong></div>${btn('Unlock offer '+icon('arrow'),`unlock:${p.id}`,'primary')}</div>`;}
function motionTour(){sheet('Experience the little details',`<p>The effects are now easier to notice. Try these moments in the demo:</p><div class="stack mt">${btn('Replay the enhanced Splash','go:splash','secondary')}${btn('Preview a reward celebration','motionreward','secondary')}${btn('Swipe & zoom a product gallery','go:offer:sofa','secondary')}${btn('Save a product to see wishlist feedback','go:products','secondary')}</div><p class="small mt">Reduced-motion preferences are respected. Browser support can affect shared-image transitions.</p>`,'motiontour');}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action;if(a.startsWith('save:')&&!state.saved.includes(a.split(':')[1]))burst(e.clientX,e.clientY);if(a.startsWith('claim:')){const id=a.split(':')[1];if(missionReady(state,id)&&!state.claims.includes(id))burst();}},true);
render();
document.addEventListener('change',e=>{if(e.target.id==='shop-sort'){shopSort=e.target.value;render();}});
document.addEventListener('submit',e=>{
 const f=e.target;if(!['search-form','login-form','register-form','forgot-form','chat-form'].includes(f.id))return;e.preventDefault();e.stopImmediatePropagation();if(!f.checkValidity()){f.reportValidity();return;}const d=new FormData(f);
 if(f.id==='search-form'){recordSearch(state,query);save();render();}
 else if(f.id==='chat-form')sendChat(d.get('message'));
 else if(f.id==='forgot-form'){sheet('Reset request preview',`<div class="success-icon">${icon('check')}</div><p>If an account exists for that email, the production app will send reset instructions. No email was sent in this concept.</p>${btn('Return to sign in','go:login','primary full')}`,'resetpassword');}
 else if(f.id==='login-form'){if(String(d.get('email')).toLowerCase().startsWith('error@')){$('#auth-error').textContent='We couldn’t sign you in. Check your sample details and try again.';return;}state.member=true;const next=pendingAuthRoute;pendingAuthRoute='home';navigate(next);toast('Signed in to the sample membership.');}
 else if(f.id==='register-form'){const name=String(d.get('name')).trim();if(!name){$('#auth-error').textContent='Please enter a first name.';return;}state=freshState();hydrate(state);state.member=false;state.name=name;state.points=0;state.pending=0;state.tierProgress=0;state.orders=[];state.activity=[];state.orderStreak=0;state.marketingPreview=d.has('marketing');navigate('verify');}
},true);
